#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0
"""Source-first M3 Commons admission: exact generated bytes, no source edits."""
from hashlib import sha256
from pathlib import Path
here = Path(__file__).resolve().parent
repo = here.parents[2]
lines = [row.split("\t") for row in (here / "manifest.tsv").read_text().splitlines() if row]
if len(lines) != 2:
    raise SystemExit("refuse: unexpected source target count")
for path, before, post, template in lines:
    if not path.startswith("src/") or ".." in Path(path).parts:
        raise SystemExit("refuse: unsafe generated target path")
    if not (here / "generated" / template).is_file() or not (repo / path).is_file():
        raise SystemExit("refuse: missing generated or product source")
    for candidate in (repo / path, here / "generated" / template):
        actual = sha256(candidate.read_bytes()).hexdigest()
        if actual != post:
            raise SystemExit("refuse: postimage mismatch " + str(candidate))
if sha256((here / "pre" / "PredicatedCollection.java.txt").read_bytes()).hexdigest() != lines[0][1]:
    raise SystemExit("refuse: original donor source preimage drift")
print("PASS M3 Commons exact canonical Java source and test parity")
